-- So'z Jangi — words table import, generated by tool/corpus/export_supabase.py
-- Source of truth: tool/corpus/out/{answers_tiered.tsv,valid_guesses.txt}
-- Practice mode's local dictionary and Daily's `words` table must never
-- diverge again — always regenerate this file from the same corpus build
-- rather than hand-editing either side.
-- Safe to re-run: ON CONFLICT (word) DO UPDATE converges existing rows
-- onto the current corpus (tier/theme/definition/is_answer_candidate).

ON CONFLICT (word) DO UPDATE SET
  length = excluded.length,
  tier = excluded.tier,
  theme = excluded.theme,
  definition_uz = excluded.definition_uz,
  is_answer_candidate = excluded.is_answer_candidate;

